/* 布局·标签页 —— 区块收进 Tab，锚点切换 */
body.l-tabbed .hero { min-height: 78vh; }
body.l-tabbed main { max-width: 1080px; margin: 0 auto; padding: 30px 24px; }
body.l-tabbed main section { display: none; padding-top: 40px; }
body.l-tabbed main section:target { display: block; }
body.l-tabbed main:not(:has(section:target)) section#projects { display: block; }
body.l-tabbed nav .nav-links a {
  border: 1.5px solid var(--border); padding: 6px 16px; border-radius: 8px 8px 0 0;
}
body.l-tabbed nav .nav-links a:hover { background: var(--surface-2); }
body.l-tabbed main::before {
  content: "点击顶部导航切换标签页"; display: block; font-size: 12.5px;
  color: var(--text-2); border-bottom: 1.5px solid var(--border);
  padding-bottom: 10px; letter-spacing: 2px;
}
body.l-tabbed main section:target,
body.l-tabbed main:not(:has(section:target)) section#projects { animation: tabfade .45s ease; }
@keyframes tabfade { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  body.l-tabbed main section:target,
  body.l-tabbed main:not(:has(section:target)) section#projects { animation: none; }
}
@media (max-width: 900px) {
  body.l-tabbed nav .nav-inner { gap: 10px; }
  body.l-tabbed nav .nav-links {
    display: flex; min-width: 0; margin-left: 0; gap: 8px;
    overflow-x: auto; scrollbar-width: thin;
  }
  body.l-tabbed nav .nav-links a {
    flex: 0 0 auto; min-height: 44px; padding: 10px 14px;
    display: inline-flex; align-items: center; white-space: nowrap;
  }
  body.l-tabbed nav .gallery-link { display: none; }
}
